        observe_signal_0();
        observe_signal_1();
        observe_signal_2();
        observe_signal_3();
      join_none
    end

    wait (status != 0);
    timer_generation++;
    if (status < 0) begin
      $fatal(1, "open_cores_benchmark_dut DPI testbench failed");
    end
    $finish;
  end

  open_cores_benchmark_dut i_dut (
      .clk(clk),
      .rst_n(rst_n),
      .cpu_prog_we(cpu_prog_we),
      .cpu_prog_addr(cpu_prog_addr),
      .cpu_prog_data(cpu_prog_data),
      .cpu_done(cpu_done),
      .cpu_trap(cpu_trap),
      .cpu_result(cpu_result),
      .cpu_instruction_count(cpu_instruction_count),
      .aes_cs(aes_cs),
      .aes_we(aes_we),
      .aes_address(aes_address),
      .aes_write_data(aes_write_data),
      .aes_read_data(aes_read_data),
      .fcs_tdata(fcs_tdata),
      .fcs_tkeep(fcs_tkeep),
      .fcs_tvalid(fcs_tvalid),
      .fcs_tready(fcs_tready),
      .fcs_tlast(fcs_tlast),
      .fcs_result(fcs_result),
      .fcs_valid(fcs_valid)
  );

endmodule : dpi_open_cores_benchmark
